<?php

declare(strict_types=1);

namespace Prex\Gifs\Domain\Favorite;

use Prex\Gifs\Domain\Favorite\Exception\InvalidFavoriteGifId;
use Prex\Shared\Domain\ValueObject\Uuid;
use Random\RandomException;

/**
 * Identity of a favorite, generated by the domain (UUID v4).
 *
 * Letting the domain create the identity - instead of relying on a database
 * auto-increment - keeps the aggregate complete before it is persisted and
 * makes the use cases testable without touching infrastructure.
 */
final readonly class FavoriteGifId
{
    private function __construct(public string $value) {}

    /**
     * @throws RandomException
     */
    public static function generate(): self
    {
        return new self(Uuid::v4());
    }

    public static function fromString(string $value): self
    {
        if (! Uuid::isValid($value)) {
            throw InvalidFavoriteGifId::withValue($value);
        }

        return new self(strtolower($value));
    }

    public function equals(self $other): bool
    {
        return $this->value === $other->value;
    }

    public function __toString(): string
    {
        return $this->value;
    }
}
